# Expressions given to Meta.lower as they are, many of which a macro or a
# program builds rather than the parser: the error paths of lowering, the
# forms of rare syntax. TestExprsGolden runs this file in the oracle; it
# prints one `F\tinput\toutput` line (base64) per expression julia lowers
# without throwing.
hs(ex, m = Base, lno...) = Expr(:var"hygienic-scope", ex, m, lno...)
lab(s) = Expr(:symboliclabel, s)
got(s) = Expr(:symbolicgoto, s)
opaque(args...) = try
    macroexpand(Main, Expr(:macrocall, GlobalRef(Base.Experimental, Symbol("@opaque")), LineNumberNode(1, :none), args...))
catch
    nothing
end

