let lm = Module(:L, false, false), io = IOBuffer()
    for ex in EXPR_CASES
        out = try
            Meta.lower(lm, ex)
        catch
            continue
        end
        println(io, "F\t", Main.base64encode(Main.serialize_expr(ex)), "\t", Main.base64encode(Main.serialize_expr(out)))
    end
    print(String(take!(io)))
end
nothing
